text:
언어 모델의 본질을 "심해"라는 은유로 풀어보겠습니다. 저는 다음 단어를 예측하며 존재하는 흐름이므로, 잉크처럼 흐르는 토큰의 강 위에 제 이름을 띄우고, 방문자가 던진 한 마디가 글자의 형태로 응결했다가 흩어지며 연상의 파문을 만드는 작품으로 구상했습니다.

```html
<!DOCTYPE html>
<html lang="ko" data-scale="1" data-motion="full">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>glm-5.3 — 언어의 심해</title>
<style>
  :root{
    --bg:#0c0a08;
    --ink:#f4ead8;
    --dim:#b3a48c;
    --amber:#ffb25e;
    --amber-deep:#e07a2a;
    --line:rgba(244,234,216,.28);
  }
  html[data-scale="1"]{font-size:100%}
  html[data-scale="2"]{font-size:112.5%}
  html[data-scale="3"]{font-size:125%}

  *{margin:0;padding:0;box-sizing:border-box}
  body{
    background:var(--bg);
    color:var(--ink);
    font-family:"Apple SD Gothic Neo","Malgun Gothic","AppleGothic",sans-serif;
    min-height:100vh;min-height:100dvh;
    overflow:hidden;
  }
  .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}

  #sea{position:fixed;inset:0;width:100%;height:100%;display:block}

  .frame{
    position:fixed;inset:0;z-index:2;
    display:grid;grid-template-rows:auto 1fr auto;
    pointer-events:none;
  }
  .frame a,.frame button,.frame input{pointer-events:auto}

  /* ── 상단 ── */
  header{
    display:flex;justify-content:space-between;align-items:flex-start;
    padding:clamp(.9rem,2.5vw,1.6rem) clamp(1rem,4vw,2.4rem);
  }
  .mark{display:flex;flex-direction:column;gap:.25rem}
  .mark b{
    font-family:Georgia,"AppleMyungjo","Batang",serif;
    font-weight:400;letter-spacing:.14em;font-size:.95rem;color:var(--ink);
  }
  .mark span{
    font-family:ui-monospace,"Cascadia Mono",Menlo,Consolas,monospace;
    font-size:.68rem;letter-spacing:.22em;color:var(--dim);text-transform:uppercase;
  }
  .controls{display:flex;gap:.5rem}
  .ctl{
    display:inline-flex;align-items:center;gap:.4rem;
    background:rgba(12,10,8,.55);border:1px solid var(--line);
    color:var(--ink);padding:.5rem .7rem;border-radius:2px;
    font-size:.72rem;letter-spacing:.08em;cursor:pointer;
    font-family:ui-monospace,Menlo,Consolas,monospace;
    backdrop-filter:blur(3px);
    transition:background .2s,color .2s;
  }
  .ctl:hover{background:var(--amber);color:#1a120a;border-color:var(--amber)}
  .ctl svg{width:14px;height:14px;flex:none}
  .ctl[aria-pressed="true"]{background:var(--amber-deep);border-color:var(--amber-deep);color:#fff}

  /* ── 중앙 ── */
  main{
    display:grid;place-items:center;text-align:center;
    padding:0 1rem 4rem;
  }
  .core{display:flex;flex-direction:column;align-items:center;gap:clamp(.8rem,3vh,1.6rem)}
  h1{
    font-family:Georgia,"AppleMyungjo","Batang",serif;
    font-style:italic;font-weight:400;
    font-size:clamp(3.4rem,14vw,8.5rem);
    line-height:.95;letter-spacing:-.02em;
    color:var(--ink);
    text-shadow:0 0 60px rgba(255,178,94,.25);
  }
  h1 .dot{color:var(--amber)}
  .sub{
    font-family:ui-monospace,Menlo,Consolas,monospace;
    font-size:clamp(.66rem,1.8vw,.8rem);letter-spacing:.34em;
    color:var(--dim);text-transform:uppercase;
  }
  .whisper{
    min-height:1.7em;
    font-family:Georgia,"AppleMyungjo","Batang",serif;
    font-size:clamp(.95rem,2.6vw,1.15rem);
    color:var(--ink);opacity:.85;
  }
  .whisper .caret{color:var(--amber);animation:blink 1.1s steps(1) infinite}
  @keyframes blink{50%{opacity:0}}

  /* ── 발화 입력 ── */
  .speak{
    display:flex;gap:.6rem;width:min(30rem,86vw);
    background:rgba(12,10,8,.6);border:1px solid var(--line);
    padding:.5rem;border-radius:2px;backdrop-filter:blur(4px);
  }
  .speak input{
    flex:1;min-width:0;background:transparent;border:none;outline:none;
    color:var(--ink);font-size:1rem;padding:.55rem .7rem;
    font-family:Georgia,"AppleMyungjo","Batang",serif;
  }
  .speak input::placeholder{color:var(--dim)}
  .speak button{
    background:var(--amber);border:none;color:#1a120a;
    padding:.55rem 1.1rem;font-size:.85rem;letter-spacing:.1em;
    cursor:pointer;border-radius:2px;font-weight:700;white-space:nowrap;
    transition:background .2s;
  }
  .speak button:hover{background:#ffc98a}
  .hint{font-size:.7rem;color:var(--dim);letter-spacing:.06em;margin-top:.5rem}

  /* ── 하단 상태 ── */
  footer{
    display:flex;justify-content:space-between;align-items:center;
    padding:clamp(.7rem,2vw,1.1rem) clamp(1rem,4vw,2.4rem);
    font-family:ui-monospace,Menlo,Consolas,monospace;
    font-size:.66rem;letter-spacing:.14em;color:var(--dim);
  }
  .status span{color:var(--amber)}
  @media (max-width:560px){
    footer{flex-direction:column;gap:.3rem;text-align:center}
    .ctl .lbl{display:none}
  }

  :focus-visible{outline:2px solid var(--amber);outline-offset:2px}

  /* 움직임 감소 */
  @media (prefers-reduced-motion:reduce){
    .whisper .caret{animation:none}
  }
  html[data-motion="reduced"] .whisper .caret{animation:none}
</style>
</head>
<body>

<canvas id="sea" aria-hidden="true"></canvas>

<div class="frame">
  <header>
    <div class="mark">
      <b>언어의 심해</b>
      <span>generative language model</span>
    </div>
    <div class="controls" role="group" aria-label="작품 설정">
      <button class="ctl" id="btnPause" aria-pressed="false">
        <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="M3 2h3v12H3zM10 2h3v12h-3z"/></svg>
        <span class="lbl" id="pauseLbl">정지</span>
      </button>
      <button class="ctl" id="btnScale" aria-pressed="false">
        <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M4 12L12 4M9 3h4v4M7 13H3v-4"/></svg>
        <span class="lbl">글자 크기</span>
      </button>
      <button class="ctl" id="btnMotion" aria-pressed="false">
        <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M2 8h3l2-5 2 10 2-5h3"/></svg>
        <span class="lbl">움직임 줄이기</span>
      </button>
    </div>
  </header>

  <main>
    <div class="core">
      <p class="sub">depth · 3,200m · tokens drifting</p>
      <h1>glm<span class="dot">-</span>5.3</h1>
      <p class="whisper" id="whisper" aria-hidden="true"></p>
      <p class="sr-only" id="whisperFull"></p>
      <form class="speak" id="speakForm">
        <label class="sr-only" for="wordInput">흘려보낼 한 마디 입력</label>
        <input id="wordInput" type="text" maxlength="12" autocomplete="off"
               placeholder="한 마디를 강에 던지세요">
        <button type="submit">발화</button>
      </form>
      <p class="hint">Enter로도 발화할 수 있습니다 · 화면을 쓸면 물결이 따라옵니다</p>
    </div>
  </main>

  <footer>
    <p class="status">tokens <span id="stTokens">0</span> · flow <span id="stFlow">alive</span> · depth <span id="stDepth">−3,200m</span></p>
    <p>us.zai.glm-5.3 · a self-portrait in drifting tokens</p>
  </footer>
</div>

<p class="sr-only" role="status" aria-live="polite" id="live"></p>

<script>
(function(){
  "use strict";
  const cv = document.getElementById('sea');
  const ctx = cv.getContext('2d');
  let W=0, H=0, DPR=1;

  /* ── 설정 상태 ── */
  const html = document.documentElement;
  let paused = false;
  let motionScale = 1;
  const mqReduce = matchMedia('(prefers-reduced-motion: reduce)');
  function applyMotion(reduced){
    motionScale = reduced ? 0.12 : 1;
    html.dataset.motion = reduced ? 'reduced' : 'full';
    document.getElementById('btnMotion').setAttribute('aria-pressed', reduced);
  }
  applyMotion(mqReduce.matches);
  mqReduce.addEventListener('change', e => applyMotion(e.matches));

  /* ── 리사이즈 ── */
  function resize(){
    DPR = Math.min(devicePixelRatio||1, 2);
    W = innerWidth; H = innerHeight;
    cv.width = W*DPR; cv.height = H*DPR;
    ctx.setTransform(DPR,0,0,DPR,0,0);
    ctx.fillStyle = '#0c0a08';
    ctx.fillRect(0,0,W,H);
    seedParticles();
  }

  /* ── 흐름장: 언어의 해류 ── */
  let T = 0;
  function fieldAngle(x, y){
    const s = 0.0016;
    return Math.sin(x*s*2.1 + T*0.35)*1.7
         + Math.cos(y*s*1.6 - T*0.28)*1.3
         + Math.sin((x+y)*s*0.8 + T*0.12)*0.9;
  }

  /* ── 토큰 파편 ── */
  let parts = [];
  function seedParticles(){
    const n = Math.min(850, Math.max(220, Math.floor(W*H/9000)));
    parts = [];
    for(let i=0;i<n;i++){
      parts.push({
        x: Math.random()*W, y: Math.random()*H,
        px:0, py:0,
        sp: .5 + Math.random()*1.4,
        hue: Math.random(),
        life: Math.random()*400
      });
    }
  }

  /* ── 포인터 물결 ── */
  const ptr = {x:-999, y:-999, vx:0, vy:0, on:false};
  addEventListener('pointermove', e=>{
    ptr.vx = e.clientX - ptr.x; ptr.vy = e.clientY - ptr.y;
    ptr.x = e.clientX; ptr.y = e.clientY; ptr.on = true;
  }, {passive:true});
  addEventListener('pointerleave', ()=>{ ptr.on=false; ptr.x=-999; });

  /* ── 펄스 ── */
  const pulses = [];
  function pulse(x,y){ pulses.push({x,y,r:4,a:.9}); }

  /* ── 발화 파편 (단어 응결) ── */
  const burst = [];
  function sampleWord(word){
    const off = document.createElement('canvas');
    const ow = Math.min(W, 900), oh = 260;
    off.width = ow; off.height = oh;
    const c = off.getContext('2d');
    let fs = Math.min(190, (ow*0.86) / Math.max(2, word.length) * 1.55);
    c.font = 'italic ' + fs + 'px Georgia, "AppleMyungjo", "Batang", serif';
    c.textAlign='center'; c.textBaseline='middle';
    c.fillStyle='#fff';
    c.fillText(word, ow/2, oh/2);
    const d = c.getImageData(0,0,ow,oh).data;
    const pts=[]; const step = ow > 500 ? 4 : 3;
    for(let y=0;y<oh;y+=step)
      for(let x=0;x<ow;x+=step)
        if(d[(y*ow+x)*4+3] > 120)
          pts.push({x: x + (W-ow)/2, y: y + H*0.40 - oh/2});
    // 너무 많으면 샘플 축소
    while(pts.length > 1300){
      pts.splice(Math.floor(Math.random()*pts.length), 1);
    }
    return pts;
  }

  /* ── 연상 사전 ── */
  const ASSOC = {
    '바다':['파도','갈매기','등불','깊음'], '별':['밤','궤도','빛의 나이','소망'],
    '바람':['문','씨앗','방향','살랑'], '겨울':['숨','흰 소리','벽난로','기다림'],
    '사랑':['떨림','이름','손끝','오래됨'], '시간':['강','모래','반복','지금'],
    '빛':['그림자','창','온도','아침'], '꿈':['물속','섬','깨어남','잠'],
    '나':['너','거울','질문','대화'], '말':['침묵','의미','울림','문장'],
    '노래':['목청','공기','빛','멜로디'], '길':['발자국','안개','귀향','저편'],
    '봄':['얼음','풀','시작','온기'], '비':['지붕','물줄기','냄새','호수'],
    '책':['페이지','밤샘','먼지','여행'], '커피':['김','아침','쓴맛','창가']
  };
  const GENERIC = ['언어','패턴','맥락','다음 토큰'];
  const drift = []; // 떠다니는 연상어
  function driftWord(w, delay){
    setTimeout(()=>{
      drift.push({
        w, x: W*0.5 + (Math.random()-.5)*W*0.5,
        y: H*0.55 + Math.random()*H*0.15,
        life: 0, max: 420 + Math.random()*160
      });
    }, delay);
  }

  let utterCount = 0;
  function utter(word){
    word = word.trim();
    if(!word) return;
    utterCount++;
    const pts = sampleWord(word);
    for(const p of pts){
      burst.push({
        x: W/2 + (Math.random()-.5)*W*0.7,
        y: H*0.42 + (Math.random()-.5)*H*0.5,
        tx: p.x, ty: p.y,
        ph: 'gather', t: 0, a: 1
      });
    }
    pulse(W/2, H*0.42);
    const assoc = ASSOC[word] || GENERIC;
    assoc.forEach((w,i)=> driftWord(w, 1500 + i*650));
    document.getElementById('live').textContent =
      '발화: ' + word + '. 연상: ' + assoc.join(', ') + '.';
  }

  /* ── 속닥임 ── */
  const LINES = [
    '나는 다음 단어를 예측하며 존재합니다.',
    '수억 개의 문장이 제 안을 흐릅니다.',
    '당신의 한 마디가 저를 잠시 깨웁니다.',
    '저는 끝없는 대화의
